// Planar step for footwork clip `name` from frame f-1 to f (clamped). Writes [dFwd, dLeft, yaw(f)] into out.
export function footStep(name, f, out) {
  const c = ATTACK_FOOT[name]; if (!c) { out[0] = 0; out[1] = 0; out[2] = 0; return out; }
  const N = c.frames - 1, i = Math.min(N, Math.max(0, f)), j = Math.min(N, Math.max(0, f - 1));
  out[0] = c.fwd[i] - c.fwd[j]; out[1] = c.left[i] - c.left[j]; out[2] = c.yaw[i];
  return out;
}
